<?php
session_start();require_once __DIR__.'/koneksi.php';require_once __DIR__.'/includes/legacy_finance_http.php';require_once __DIR__.'/includes/legacy_full.php';require_once __DIR__.'/includes/legacy_operational_history.php';
$kind=is_string($_GET['kind']??null)?$_GET['kind']:'history';$labels=['history'=>'Histori Sebelum 2020','unidentified'=>'Catatan Belum Teridentifikasi','du_anomaly'=>'Referensi Anomali DU','zero_journal'=>'Referensi Jurnal Nol','all'=>'Semua Catatan Terpisah'];$title=$labels[$kind]??'Catatan Legacy';$error='';$result=['rows'=>[],'total'=>0,'page'=>1];
try{lf_http_bootstrap($koneksi);if($_SERVER['REQUEST_METHOD']!=='GET')throw new DomainException('Metode tidak diizinkan.',405);
    if(!is_string($_GET['id']??null))throw new DomainException('Pekerjaan tidak valid.',400);$id=$_GET['id'];$job=legacy_job($id);
    if(($job['category']??'')!=='full'||(unit_active_id()!==0&&unit_active_id()!==(int)$job['unit']))throw new DomainException('Unit pekerjaan tidak sesuai.',403);
    $csv=($_GET['format']??'')==='csv';$result=lop_history_search($koneksi,$job,$_GET,$csv);
    if($csv){header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="catatan-legacy.csv"');$out=fopen('php://output','w');fputcsv($out,['Tanggal Sumber','Tabel','Jenis','Nominal Asli','Data Asli']);foreach($result['rows'] as $r)fputcsv($out,array_map('lf_csv_cell',[$r['date'],$r['source_table'],$r['kind'],lf_json($r['amounts']),lf_json($r['raw'])]));exit;}
}catch(DomainException|InvalidArgumentException $e){if($e->getCode()===403){http_response_code(403);exit('Hanya Super Admin pada unit yang sesuai dapat membaca histori.');}http_response_code(in_array($e->getCode(),[400,403,404,405],true)?$e->getCode():409);$error=$e->getMessage();}
catch(Throwable $e){error_log('Legacy history: '.$e->getMessage());http_response_code(500);$error='Histori belum dapat dibaca. Muat ulang halaman.';}
function lh_e(mixed $v): string{return htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');}
?><!doctype html><html lang="id" data-palette="<?= unit_palette_for_view() ?>"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Histori Legacy Tanpa Pemilik</title><link rel="stylesheet" href="assets/css/style.css"><link rel="stylesheet" href="assets/css/backup_restore.css"><link rel="stylesheet" href="assets/css/legacy_finance.css"><link rel="stylesheet" href="assets/css/legacy_full.css"><link rel="stylesheet" href="assets/css/legacy_ui.css?v=<?= filemtime(__DIR__.'/assets/css/legacy_ui.css') ?>"><script>document.documentElement.dataset.theme=localStorage.getItem('spp_theme')||'light';</script></head><body><div class="layout"><?php legacy_ui_sidebar(); ?><main class="main-content dbt-main"><div class="db-tools-page legacy-ui lf-page lop-review"><header class="dbt-heading"><div><h1><?= lh_e($title) ?></h1><p>Sumber asli tetap tersimpan. Catatan ini tidak menambah saldo aktif, tagihan, penerimaan, atau pengembalian kas.</p></div><a class="dbt-button" href="legacy_operational_review.php?id=<?= lh_e($id??'') ?>">Kembali ke Migrasi</a></header>
<?php if($error): ?><p class="dbt-warning" role="alert"><?= lh_e($error) ?></p><?php else: ?><nav class="legacy-sections" aria-label="Jenis catatan"><?php foreach($labels as $value=>$label): ?><a href="?<?= lh_e(http_build_query(['id'=>$id,'kind'=>$value])) ?>" <?= $kind===$value?'aria-current="page"':'' ?>><?= lh_e($label) ?></a><?php endforeach; ?></nav><section class="dbt-card"><form method="get" class="lf-form"><input type="hidden" name="kind" value="<?= lh_e($kind) ?>"><input type="hidden" name="id" value="<?= lh_e($id) ?>"><div class="lful-grid"><label>Pencarian<input name="q" value="<?= lh_e($_GET['q']??'') ?>" placeholder="Tabel atau informasi sumber"></label><label>Dari tanggal<input type="date" name="date_from" value="<?= lh_e($_GET['date_from']??'') ?>"></label><label>Sampai tanggal<input type="date" name="date_to" value="<?= lh_e($_GET['date_to']??'') ?>"></label></div><div class="legacy-actions"><button class="dbt-button dbt-button-primary">Cari Histori</button><a class="dbt-button" href="?id=<?= lh_e($id) ?>">Reset</a><button class="dbt-button" name="format" value="csv">Unduh CSV</button></div></form></section><section class="dbt-card"><h2><?= (int)$result['total'] ?> <?= $kind==='history'?'catatan histori':'catatan sumber' ?></h2><div class="dbt-table-scroll"><table class="dbt-table"><thead><tr><th>Tanggal Sumber</th><th>Jenis</th><th>Nominal Asli</th><th>Rincian</th></tr></thead><tbody><?php foreach($result['rows'] as $r): ?><tr><td><?= lh_e($r['date']?spp_date_label($r['date']):'Tanggal tidak tercatat') ?></td><td><?= lh_e(['empty_reference'=>'Referensi sumber kosong','history_unowned'=>'Histori tanpa pemilik','unidentified'=>'Menunggu pemilik','du_anomaly'=>'Referensi Anomali DU','zero_journal'=>'Referensi jurnal nol'][$r['kind']]) ?></td><td><?php legacy_ui_amounts(lf_json($r['amounts'])); ?></td><td><details><summary>Lihat sumber</summary><p>Tabel: <?= lh_e($r['source_table']) ?></p><pre><?= lh_e(json_encode($r['raw'],JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE)) ?></pre></details></td></tr><?php endforeach; ?></tbody></table></div><nav class="legacy-actions"><?php foreach([-1=>'Sebelumnya',1=>'Berikutnya'] as $delta=>$label):$next=$result['page']+$delta;if($next<1||($next-1)*25>=$result['total'])continue; ?><a class="dbt-button" href="?<?= lh_e(http_build_query(array_replace(array_intersect_key($_GET,array_flip(['id','q','date_from','date_to','kind'])),['page'=>$next]))) ?>"><?= $label ?></a><?php endforeach; ?></nav></section><?php endif; ?></div></main></div><script src="assets/js/app.js?v=<?= filemtime(__DIR__.'/assets/js/app.js') ?>"></script></body></html>
